// Python-flavoured exception objects and the CPython-style crash report.
//
// The reference program lets a ValueError escape to the top level, so the
// interpreter prints a traceback on stderr and exits with status 1.  Only the
// exception classes and that final report live here.

/** Base class for every emulated Python exception. */
export class PyError extends Error {
  constructor(pyType, message) {
    super(message);
    this.pyType = pyType;
  }

  /** `TypeName: message`, the way Python renders an uncaught exception. */
  formatException() {
    return this.message === '' ? this.pyType : `${this.pyType}: ${this.message}`;
  }
}

export class PyValueError extends PyError {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyTypeError extends PyError {
  constructor(message) {
    super('TypeError', message);
  }
}

/**
 * Write an uncaught exception the way CPython does: the traceback header, the
 * offending frame, then the exception line.  `frames` are rendered outermost
 * first, matching "most recent call last".
 */
export function formatTraceback(err, frames) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    if (frame.source !== undefined) {
      lines.push(`    ${frame.source}`);
    }
    if (frame.caret !== undefined) {
      lines.push(`    ${frame.caret}`);
    }
  }
  lines.push(err instanceof PyError ? err.formatException() : String(err));
  return lines.join('\n') + '\n';
}

