// Unicode helpers needed to mimic `str.strip()` and `int()` character classes.

// Characters Python treats as whitespace when parsing a numeric literal.  This
// is the Unicode White_Space property: it includes NEL (U+0085), NBSP and the
// space separators, but *not* U+200B or the BOM, and not the C0 separators
// U+001C..U+001F.
const WHITESPACE = new Set(
  [
    0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20, 0x85, 0xa0, 0x1680, 0x2028, 0x2029,
    0x202f, 0x205f, 0x3000,
  ].concat(Array.from({ length: 11 }, (_, i) => 0x2000 + i)) // U+2000..U+200A
);

export function isPySpace(ch) {
  return WHITESPACE.has(ch.codePointAt(0));
}

/** Python's `str.strip()` restricted to the whitespace set above. */
export function pyStrip(text) {
  const chars = Array.from(text);
  let start = 0;
  let end = chars.length;
  while (start < end && isPySpace(chars[start])) start += 1;
  while (end > start && isPySpace(chars[end - 1])) end -= 1;
  return chars.slice(start, end).join('');
}

const DECIMAL_DIGIT = /^\p{Nd}$/u;

export function isDecimalDigit(ch) {
  return DECIMAL_DIGIT.test(ch);
}

/**
 * Numeric value of any Unicode decimal digit (category Nd), so that `int()`
 * accepts e.g. Arabic-Indic '٣' exactly like Python does.
 *
 * Every Nd set is ten consecutive code points ordered 0..9, so walking back to
 * the start of the surrounding run of Nd characters and taking the offset
 * modulo ten yields the digit even where several sets sit side by side (the
 * mathematical digit blocks at U+1D7CE..U+1D7FF, for instance).
 */
export function decimalDigitValue(ch) {
  if (!isDecimalDigit(ch)) return -1;
  const cp = ch.codePointAt(0);
  let runStart = cp;
  while (runStart > 0 && isDecimalDigit(String.fromCodePoint(runStart - 1))) {
    runStart -= 1;
  }
  return (cp - runStart) % 10;
}

