// `int(text)` for base 10, returning a BigInt so arbitrary precision is kept.

import { PyValueError } from '../errors/pyerrors.mjs';
import { decimalDigitValue, isDecimalDigit, pyStrip } from './unicodedata.mjs';
import { pyReprStr } from './repr.mjs';

/**
 * Parse a decimal integer with Python's rules: surrounding whitespace is
 * ignored, an optional sign may lead, underscores may separate digits (never
 * doubled, never at either end), and any Unicode decimal digit counts.
 *
 * @param {string} text
 * @returns {bigint}
 */
export function pyInt(text) {
  const body = pyStrip(text);
  const chars = Array.from(body);
  let i = 0;
  let negative = false;
  if (chars[i] === '+' || chars[i] === '-') {
    negative = chars[i] === '-';
    i += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; i < chars.length; i += 1) {
    const ch = chars[i];
    if (ch === '_') {
      // An underscore is only legal wedged between two digits.
      if (!previousWasDigit) return invalid(text);
      previousWasDigit = false;
      continue;
    }
    const value = decimalDigitValue(ch);
    if (value < 0) return invalid(text);
    digits += String(value);
    previousWasDigit = true;
  }

  if (digits === '' || !previousWasDigit) return invalid(text);
  const magnitude = BigInt(digits);
  // -0 collapses to 0, as `int('-0')` does.
  return negative ? -magnitude : magnitude;
}

function invalid(text) {
  throw new PyValueError(
    `invalid literal for int() with base 10: ${pyReprStr(text)}`
  );
}

export { isDecimalDigit };

