// Minimal stand-ins for the two Python containers this program prints:
// a tuple and an insertion-ordered dict.

import { pyRepr, pyReprList, pyReprTuple } from './repr.mjs';

/** An immutable tuple; only construction and repr are needed. */
export class PyTuple {
  constructor(items) {
    this.items = items;
  }

  get length() {
    return this.items.length;
  }

  [Symbol.iterator]() {
    return this.items[Symbol.iterator]();
  }

  __pyRepr__() {
    return pyReprTuple(this.items);
  }
}

export function pyTuple(...items) {
  return new PyTuple(items);
}

/**
 * Canonical form of a dict key.  Python hashes `True` and `1` alike, so both
 * must land in the same slot while the key first inserted keeps its identity in
 * the repr.
 */
function keyToken(key) {
  if (typeof key === 'boolean') return `i:${key ? 1 : 0}`;
  if (typeof key === 'bigint') return `i:${key}`;
  if (typeof key === 'number' && Number.isInteger(key)) return `i:${key}`;
  if (typeof key === 'string') return `s:${key}`;
  if (key === null || key === undefined) return 'None';
  return `o:${String(key)}`;
}

/** A dict that keeps insertion order and reprs like Python's. */
export class PyDict {
  constructor() {
    this.slots = new Map(); // token -> { key, value }
  }

  has(key) {
    return this.slots.has(keyToken(key));
  }

  get(key) {
    const slot = this.slots.get(keyToken(key));
    return slot === undefined ? undefined : slot.value;
  }

  set(key, value) {
    const token = keyToken(key);
    const slot = this.slots.get(token);
    if (slot === undefined) {
      this.slots.set(token, { key, value });
    } else {
      slot.value = value; // the original key object is retained, as in Python
    }
    return this;
  }

  /** dict.setdefault(): insert the factory's result only when absent. */
  setDefault(key, factory) {
    const token = keyToken(key);
    const slot = this.slots.get(token);
    if (slot !== undefined) return slot.value;
    const value = factory();
    this.slots.set(token, { key, value });
    return value;
  }

  get size() {
    return this.slots.size;
  }

  *entries() {
    for (const { key, value } of this.slots.values()) yield [key, value];
  }

  keys() {
    return Array.from(this.slots.values(), (slot) => slot.key);
  }

  __pyRepr__() {
    const parts = [];
    for (const [key, value] of this.entries()) {
      const rendered = Array.isArray(value) ? pyReprList(value) : pyRepr(value);
      parts.push(`${pyRepr(key)}: ${rendered}`);
    }
    return `{${parts.join(', ')}}`;
  }
}

