  get size() {
    return this.slots.size;
  }

  *entries() {
    for (const { key, value } of this.slots.values()) yield [key, value];
  }

  keys() {
    return Array.from(this.slots.values(), (slot) => slot.key);
  }

  __pyRepr__() {
    const parts = [];
    for (const [key, value] of this.entries()) {
      const rendered = Array.isArray(value) ? pyReprList(value) : pyRepr(value);
      parts.push(`${pyRepr(key)}: ${rendered}`);
    }
    return `{${parts.join(', ')}}`;
