// Key-function plumbing shared by the iterutils helpers.

import { PyTypeError } from '../errors/pyerrors.mjs';

/** Python's `bool()` for the values this library sees. */
export function isTruthy(value) {
  if (typeof value === 'bigint') return value !== 0n;
  if (value === null || value === undefined) return false;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === 'string') return value.length > 0;
  return Boolean(value);
}

/**
 * Accept either a callable or an attribute name, mirroring the `key` argument
 * of the boltons helpers.
 */
export function makeKeyFunction(key) {
  if (typeof key === 'function') return key;
  if (typeof key === 'string') return (obj) => obj[key];
  throw new PyTypeError('expected callable or string, not ' + typeof key);
}

