import { PyTypeError } from '../errors/pyerrors.mjs';
import { PyDict } from '../pytypes/containers.mjs';
import { isTruthy, makeKeyFunction } from './keyfunc.mjs';

/**
 * Group an iterable into a dict of lists keyed by `key(item)`.
 *
 * Keys appear in the order they are first produced, and each bucket keeps the
 * source order of its members.
 *
 * @param {Iterable<any>} src
 * @param {Function|string} [key] grouping function, or attribute name
 * @param {object} [options]
 * @param {Function} [options.valueTransform] applied to each item before it is stored
 * @param {Function} [options.keyFilter] only keys passing this filter are kept
 * @returns {PyDict}
 */
export function bucketize(src, key = isTruthy, options = {}) {
  if (src === null || src === undefined) {
    throw new PyTypeError('expected an iterable, not None');
  }
  const keyFunc = makeKeyFunction(key);
  const { valueTransform, keyFilter } = options;
  if (valueTransform !== undefined && typeof valueTransform !== 'function') {
    throw new PyTypeError('expected callable or None for valueTransform');
  }
  if (keyFilter !== undefined && typeof keyFilter !== 'function') {
    throw new PyTypeError('expected callable or None for keyFilter');
  }

  const buckets = new PyDict();
  for (const item of src) {
    const bucketKey = keyFunc(item);
    const value = valueTransform === undefined ? item : valueTransform(item);
    buckets.setDefault(bucketKey, () => []).push(value);
  }

  if (keyFilter === undefined) return buckets;
  const filtered = new PyDict();
  for (const [bucketKey, values] of buckets.entries()) {
    if (isTruthy(keyFilter(bucketKey))) filtered.set(bucketKey, values);
  }
  return filtered;
}

