// Synchronous stdout/stderr writes.
//
// `process.stdout.write` is asynchronous on pipes, so a following
// `process.exit()` can drop buffered bytes.  Writing through the file
// descriptor keeps Python's ordering guarantees around a crash or `sys.exit`.

import { writeSync } from 'node:fs';

function writeFd(fd, text) {
  const buffer = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (err) {
      if (err.code === 'EAGAIN') continue; // non-blocking pipe: retry
      if (err.code === 'EPIPE') return; // reader went away, as with SIGPIPE
      throw err;
    }
  }
}

export function writeStdout(text) {
  writeFd(1, text);
}

export function writeStderr(text) {
  writeFd(2, text);
}

