// Argument actions: the behaviours `add_argument` can attach to an option.

export const STORE = 'store';
export const HELP = 'help';

/**
 * One declared option.  Only the pieces the source program relies on are
 * modelled: a single-value store and the automatic help flag.
 */
export class Action {
  constructor({ optionStrings, dest, kind, type, required, help, metavar }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.kind = kind;
    this.type = type ?? ((value) => value);
    this.required = required ?? false;
    this.help = help ?? '';
    this.metavar = metavar ?? (dest === null ? null : dest.toUpperCase());
  }

  /** How many command-line values the option swallows. */
  get nargs() {
    return this.kind === HELP ? 0 : 1;
  }

  /** `--a A` / `-h, --help`, as shown in usage and help listings. */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    return this.optionStrings.map((opt) => `${opt} ${this.metavar}`).join(', ');
  }

  /** The bracketed form used in the usage line. */
  formatUsage() {
    const head = this.optionStrings[0];
    const part = this.nargs === 0 ? head : `${head} ${this.metavar}`;
    return this.required ? part : `[${part}]`;
  }
}

