// Usage and help text layout, matching argparse's HelpFormatter.

const MAX_HELP_POSITION = 24;
const MIN_HELP_WIDTH = 11;
const INDENT = 2;

/** Terminal width argparse would use: $COLUMNS, else the tty, else 80. */
export function terminalWidth() {
  const fromEnv = Number.parseInt(process.env.COLUMNS ?? '', 10);
  if (Number.isInteger(fromEnv) && fromEnv > 0) return fromEnv - 2;
  if (process.stdout.isTTY && process.stdout.columns > 0) {
    return process.stdout.columns - 2;
  }
  return 80 - 2;
}

/** Greedy word wrap, as textwrap.wrap does for help strings. */
function wrap(text, width) {
  const words = text.split(/\s+/u).filter((word) => word !== '');
  if (words.length === 0) return [];
  const lines = [];
  let line = words[0];
  for (const word of words.slice(1)) {
    if (line.length + 1 + word.length <= width) {
      line += ' ' + word;
    } else {
      lines.push(line);
      line = word;
    }
  }
  lines.push(line);
  return lines;
}

/** `usage: prog [-h] --a A`, wrapped onto continuation lines when too wide. */
export function formatUsage(prog, actions) {
  const prefix = 'usage: ';
  const parts = actions.map((action) => action.formatUsage());
  const oneLine = `${prefix}${prog}${parts.length ? ' ' + parts.join(' ') : ''}`;
  const width = terminalWidth();
  if (oneLine.length <= width) return oneLine + '\n';

  // Too wide: keep the program name on the first line and align the rest under
  // the column just after it.
  const pad = ' '.repeat(prefix.length + prog.length + 1);
  const lines = [];
  let line = `${prefix}${prog}`;
  for (const part of parts) {
    if (line.length + 1 + part.length > width && line.trim() !== `${prefix}${prog}`.trim()) {
      lines.push(line);
      line = pad + part;
    } else if (line.length + 1 + part.length > width) {
      lines.push(line);
      line = pad + part;
    } else {
      line += ' ' + part;
    }
  }
  lines.push(line);
  return lines.join('\n') + '\n';
}

/** The full `--help` output. */
export function formatHelp(prog, actions) {
  let out = formatUsage(prog, actions);
  out += '\n';
  out += 'options:\n';

  const invocations = actions.map((action) => action.formatInvocation());
  const maxLength = invocations.reduce(
    (max, invocation) => Math.max(max, invocation.length + INDENT),
    0
  );
  const helpPosition = Math.min(maxLength + 2, MAX_HELP_POSITION);
  const actionWidth = helpPosition - INDENT - 2;
  const helpWidth = Math.max(terminalWidth() - helpPosition, MIN_HELP_WIDTH);

  actions.forEach((action, index) => {
    const invocation = invocations[index];
    if (action.help === '') {
      out += `${' '.repeat(INDENT)}${invocation}\n`;
      return;
    }
    const helpLines = wrap(action.help, helpWidth);
    if (invocation.length <= actionWidth) {
      const header = ' '.repeat(INDENT) + invocation.padEnd(actionWidth, ' ') + '  ';
      out += `${header}${helpLines[0]}\n`;
    } else {
      out += `${' '.repeat(INDENT)}${invocation}\n`;
      out += `${' '.repeat(helpPosition)}${helpLines[0]}\n`;
    }
    for (const line of helpLines.slice(1)) {
      out += `${' '.repeat(helpPosition)}${line}\n`;
    }
  });

  return out;
}

