// A small argparse port: enough of ArgumentParser to reproduce the reference
// program's command line, including its error messages and exit codes.

import { basename } from 'node:path';
import { writeStderr, writeStdout } from '../io/stdio.mjs';
import { Action, HELP, STORE } from './actions.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';

// argparse's own test for "this looks like a negative number, not a flag".
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/u;

export class ArgumentParser {
  constructor({ prog, addHelp = true } = {}) {
    this.prog = prog ?? basename(process.argv[1] ?? 'prog');
    this.actions = [];
    this.optionStringActions = new Map();
    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * Declare an option.  `names` is one option string or a list of them; the
   * destination is derived from the first long name, as argparse does.
   */
  addArgument(names, { action = 'store', type, required, help, metavar, dest } = {}) {
    const optionStrings = Array.isArray(names) ? names : [names];
    const kind = action === 'help' ? HELP : STORE;
    const longName = optionStrings.find((opt) => opt.startsWith('--')) ?? optionStrings[0];
    const resolvedDest =
      kind === HELP ? 'help' : dest ?? longName.replace(/^-+/u, '').replace(/-/gu, '_');

    const created = new Action({
      optionStrings,
      dest: resolvedDest,
      kind,
      type,
      required,
      help,
      metavar,
    });
    this.actions.push(created);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, created);
    }
    return created;
  }

  /** Name argparse uses when it mentions an action in an error message. */
  static actionName(action) {
    return action.optionStrings.join('/');
  }

  get hasNegativeNumberOptions() {
    return Array.from(this.optionStringActions.keys()).some((opt) =>
      NEGATIVE_NUMBER.test(opt)
    );
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** Report a usage error on stderr and exit with status 2. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /**
   * Decide whether a token is an option or a plain value, following
   * argparse's `_parse_optional` step by step.
   */
  classify(token) {
    if (!token.startsWith('-')) return { type: 'A' };

    const exact = this.optionStringActions.get(token);
    if (exact !== undefined) {
      return { type: 'O', action: exact, optionString: token, explicitArg: null };
    }

    if (token.length === 1) return { type: 'A' }; // a bare '-'

    if (token.includes('=')) {
      const splitAt = token.indexOf('=');
      const optionString = token.slice(0, splitAt);
      const explicitArg = token.slice(splitAt + 1);
      const action = this.optionStringActions.get(optionString);
      if (action !== undefined) return { type: 'O', action, optionString, explicitArg };
    }

    const matches = this.optionTuples(token);
    if (matches.length > 1) {
      const options = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];

    if (NEGATIVE_NUMBER.test(token) && !this.hasNegativeNumberOptions) {
      return { type: 'A' };
    }
    if (token.includes(' ')) return { type: 'A' };

    return { type: 'O', unknown: true };
  }

  /** Abbreviation and clustered-short-flag candidates for a token. */
  optionTuples(token) {
    const results = [];
    const isLong = token.startsWith('--');
    const splitAt = token.indexOf('=');
    const prefix = splitAt === -1 ? token : token.slice(0, splitAt);
    const explicit = splitAt === -1 ? null : token.slice(splitAt + 1);

    if (isLong) {
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) {
          results.push({ type: 'O', action, optionString, explicitArg: explicit });
        }
      }
      return results;
    }

    // Single dash: either an abbreviation of a longer option string, or a short
    // option carrying its value directly ("-hx" -> "-h" plus "x").
    const shortOption = token.slice(0, 2);
    const shortExplicit = token.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (splitAt === -1 && optionString === shortOption) {
        results.push({
          type: 'O',
          action,
          optionString: shortOption,
          explicitArg: shortExplicit === '' ? null : shortExplicit,
        });
      } else if (optionString.startsWith(prefix)) {
        results.push({ type: 'O', action, optionString, explicitArg: explicit });
      }
    }
    return results;
  }

  /** parse_args(): like parse_known_args, but leftovers are an error. */
