// Usage and help text layout, matching argparse's HelpFormatter.

import { wrapText } from './textwrap.mjs';

const MAX_HELP_POSITION = 24;
const MIN_HELP_WIDTH = 11;
const INDENT = 2;

// How argparse chops a usage string into wrappable pieces: a bracketed or
// parenthesised group stays whole, everything else breaks on whitespace.
const USAGE_PART = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/gu;

/** Terminal width argparse would use: $COLUMNS, else the tty, else 80. */
export function terminalWidth() {
  const fromEnv = Number.parseInt(process.env.COLUMNS ?? '', 10);
  if (Number.isInteger(fromEnv) && fromEnv > 0) return fromEnv - 2;
  if (process.stdout.isTTY && process.stdout.columns > 0) {
    return process.stdout.columns - 2;
  }
  return 80 - 2;
}

/**
 * Pack usage parts onto lines no wider than `textWidth`.
 *
 * `prefix` is only passed for the first group of lines, where the leading
 * indent is already taken up by "usage: " plus the program name.
 */
function getLines(parts, indent, textWidth, prefix) {
  const lines = [];
  let line = [];
  let lineLen = (prefix === undefined ? indent.length : prefix.length) - 1;
  for (const part of parts) {
    if (lineLen + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (prefix !== undefined && lines.length > 0) {
    lines[0] = lines[0].slice(indent.length);
  }
  return lines;
}

/** `usage: prog [-h] --a A`, wrapped the way argparse wraps it. */
export function formatUsage(prog, actions, width = terminalWidth()) {
  const prefix = 'usage: ';
  const optionalsUsage = actions.map((action) => action.formatUsage()).join(' ');
  let usage = [prog, optionalsUsage].filter((part) => part !== '').join(' ');

  if (prefix.length + usage.length > width) {
    const parts = optionalsUsage.match(USAGE_PART) ?? [];
    let lines;
    if (prefix.length + prog.length <= 0.75 * width) {
      // Short program name: the first options follow it on line one.
      const indent = ' '.repeat(prefix.length + prog.length + 1);
      lines =
        parts.length > 0 ? getLines([prog, ...parts], indent, width, prefix) : [prog];
    } else {
      // Long program name: it gets a line of its own.
      const indent = ' '.repeat(prefix.length);
      lines = [prog, ...getLines(parts, indent, width)];
    }
    usage = lines.join('\n');
  }

  return prefix + usage + '\n';
}

/** The full `--help` output. */
export function formatHelp(prog, actions) {
  const width = terminalWidth();
  let out = formatUsage(prog, actions, width);
  out += '\n';
  out += 'options:\n';

  const invocations = actions.map((action) => action.formatInvocation());
  const maxLength = invocations.reduce(
    (max, invocation) => Math.max(max, invocation.length + INDENT),
    0
  );
  // argparse shrinks the help column on narrow terminals.
  const maxHelpPosition = Math.min(
    MAX_HELP_POSITION,
    Math.max(width - 20, INDENT * 2)
  );
  const helpPosition = Math.min(maxLength + 2, maxHelpPosition);
  const actionWidth = Math.max(helpPosition - INDENT - 2, 1);
  const helpWidth = Math.max(width - helpPosition, MIN_HELP_WIDTH);

  actions.forEach((action, index) => {
    const invocation = invocations[index];
    if (action.help === '') {
      out += `${' '.repeat(INDENT)}${invocation}\n`;
      return;
    }
    const helpLines = wrapText(action.help, helpWidth);
    if (invocation.length <= actionWidth) {
      out += ' '.repeat(INDENT) + invocation.padEnd(actionWidth, ' ') + '  ';
      out += `${helpLines[0]}\n`;
    } else {
      out += `${' '.repeat(INDENT)}${invocation}\n`;
      out += `${' '.repeat(helpPosition)}${helpLines[0]}\n`;
    }
    for (const line of helpLines.slice(1)) {
      out += `${' '.repeat(helpPosition)}${line}\n`;
    }
  });

  return out;
}

