// A stand-in for Python's `linecache`, used when rendering a traceback.
//
// CPython looks the frame's file up relative to the current directory, so the
// source line appears in the traceback only when the script is reachable from
// where the program was started.

import { readFileSync } from 'node:fs';
import { isAbsolute, resolve } from 'node:path';

const cache = new Map();

/**
 * Line `lineNumber` (1-based) of `file`, or null when the file cannot be read.
 * The trailing newline is not included.
 */
export function getLine(file, lineNumber) {
  const path = isAbsolute(file) ? file : resolve(process.cwd(), file);
  if (!cache.has(path)) {
    try {
      cache.set(path, readFileSync(path, 'utf8').split('\n'));
    } catch {
      cache.set(path, null);
    }
  }
  const lines = cache.get(path);
  if (lines === null || lineNumber < 1 || lineNumber > lines.length) return null;
  return lines[lineNumber - 1].replace(/\r$/u, '');
}

