// Python-flavoured exception objects and the CPython-style crash report.
//
// The reference program lets a ValueError escape to the top level, so the
// interpreter prints a traceback on stderr and exits with status 1.  Only the
// exception classes and that final report live here.

import { getLine } from './linecache.mjs';

/** Base class for every emulated Python exception. */
export class PyError extends Error {
  constructor(pyType, message) {
    super(message);
    this.pyType = pyType;
  }

  /** `TypeName: message`, the way Python renders an uncaught exception. */
  formatException() {
    return this.message === '' ? this.pyType : `${this.pyType}: ${this.message}`;
  }
}

export class PyValueError extends PyError {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyTypeError extends PyError {
  constructor(message) {
    super('TypeError', message);
  }
}

/**
 * Render one traceback frame: the location line, then — only when the source is
 * still on disk, as linecache requires — the statement and the `^` anchors
 * under the sub-expression that raised.
 */
function formatFrame({ file, line, name, colStart, colEnd }) {
  const lines = [`  File "${file}", line ${line}, in ${name}`];
  const source = getLine(file, line);
  if (source === null || source.trim() === '') return lines;

  const stripped = source.trim();
  lines.push(`    ${stripped}`);
  if (colStart !== undefined && colEnd !== undefined) {
    // Column offsets are recorded against the raw line; shift them by the
    // indentation that `strip()` removed.
    const shift = source.length - source.trimStart().length;
    const start = Math.max(colStart - shift, 0);
    const end = Math.min(colEnd - shift, stripped.length);
    // Python omits the anchors when they would span the whole statement.
    if (end > start && !(start === 0 && end === stripped.length)) {
      lines.push(`    ${' '.repeat(start)}${'^'.repeat(end - start)}`);
    }
  }
  return lines;
}

/**
 * Write an uncaught exception the way CPython does: the traceback header, the
 * offending frames (outermost first, matching "most recent call last"), then
 * the exception line.
 */
export function formatTraceback(err, frames) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(...formatFrame(frame));
  }
  lines.push(err instanceof PyError ? err.formatException() : String(err));
  return lines.join('\n') + '\n';
}

