#!/usr/bin/env node
// Port of dataset/test7.py: partition and bucketize a comma-separated list.

import { ArgumentParser } from './lib/argparse/index.mjs';
import { bucketize, partition } from './lib/iterutils/index.mjs';
import { pyPrint } from './lib/io/print.mjs';
import { pyInt } from './lib/pytypes/pyint.mjs';
import { PyError, formatTraceback } from './lib/errors/pyerrors.mjs';
import { writeStderr } from './lib/io/stdio.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', {
    type: String,
    required: true,
    help: 'Comma-separated numbers',
  });
  const args = parser.parseArgs();

  const numbers = args.a.split(',').map((x) => pyInt(x));

  const result1 = partition(numbers, (x) => x % 2n === 0n); // even / odd
  pyPrint(result1);
  const result2 = partition(numbers, (x) => x > 0n); // positive / negative
  pyPrint(result2);
  const result3 = bucketize(numbers, (x) => x % 2n === 0n); // grouped by parity
  pyPrint(result3);
  const result4 = bucketize(numbers, (x) => x > 10n); // grouped by "> 10"
  pyPrint(result4);
}

try {
  main();
} catch (err) {
  if (!(err instanceof PyError)) throw err;
  // Same shape as the uncaught ValueError the reference program dies with.
  writeStderr(
    formatTraceback(err, [
      {
        file: 'test7.py',
        line: 8,
        name: '<module>',
        source: "numbers = [int(x) for x in args.a.split(',')]",
        caret: '           ^^^^^^',
      },
    ])
  );
  process.exit(1);
}

