// `repr()` for the handful of Python types this program prints.

// Everything Python escapes inside a string literal: the C* categories plus the
// line/paragraph/space separators.  Plain U+0020 stays literal.
const UNPRINTABLE = /[\p{C}\p{Zl}\p{Zp}\p{Zs}]/u;

function escapeCodePoint(cp) {
  if (cp < 0x100) return `\\x${cp.toString(16).padStart(2, '0')}`;
  if (cp < 0x10000) return `\\u${cp.toString(16).padStart(4, '0')}`;
  return `\\U${cp.toString(16).padStart(8, '0')}`;
}

/** `repr()` of a str: single quotes unless that would need escaping. */
export function pyReprStr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of text) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (ch !== ' ' && UNPRINTABLE.test(ch)) out += escapeCodePoint(ch.codePointAt(0));
    else out += ch;
  }
  return out + quote;
}

/** `repr()` of a list. */
export function pyReprList(items) {
  return `[${items.map(pyRepr).join(', ')}]`;
}

/** `repr()` of a tuple, including the lone trailing comma of a 1-tuple. */
export function pyReprTuple(items) {
  if (items.length === 1) return `(${pyRepr(items[0])},)`;
  return `(${items.map(pyRepr).join(', ')})`;
}

/** `repr()` of an arbitrary value. */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'string') return pyReprStr(value);
  if (typeof value === 'number') {
    // Integral doubles still print without a fractional part in Python only
    // for ints; a float always shows one.
    return Number.isInteger(value) && !Object.is(value, -0)
      ? String(value)
      : formatFloat(value);
  }
  if (Array.isArray(value)) return pyReprList(value);
  if (typeof value.__pyRepr__ === 'function') return value.__pyRepr__();
  return String(value);
}

function formatFloat(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  if (Number.isInteger(value)) return `${value === 0 && Object.is(value, -0) ? '-0' : value}.0`;
  return String(value);
}

/** `print(value)` — repr for containers, str() for plain strings. */
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

